#include <QGuiApplication>
#include <KSystemClipboard>
#include <QMimeData>
#include <QProcess>
#include <QDebug>
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <dirent.h>
#include <unistd.h>
#include <signal.h>

static int count_open_fds() {
    int count = 0;
    DIR *dir = opendir("/proc/self/fd");
    if (!dir) return -1;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] != '.') count++;
    }
    closedir(dir);
    return count;
}

int main(int argc, char *argv[]) {
    QGuiApplication app(argc, argv);
    KSystemClipboard *cb = KSystemClipboard::instance();

    std::cout << "==========================================================" << std::endl;
    std::cout << "CHALLENGER 1: KSYSTEMCLIPBOARD EMPIRICAL STRESS HARNESS" << std::endl;
    std::cout << "==========================================================" << std::endl;
    std::cout << "Platform: " << QGuiApplication::platformName().toStdString() << std::endl;
    std::cout << "Initial open FDs: " << count_open_fds() << std::endl;

    if (!cb) {
        std::cerr << "FAIL: KSystemClipboard returned null!" << std::endl;
        return 1;
    }

    // STRESS TEST 1: Large Payload (1 MB and 10 MB text)
    std::cout << "\n[TEST 1] Testing Large Payloads across 64KB Linux Pipe Buffer Boundary..." << std::endl;
    for (size_t size_mb : {1, 5, 10}) {
        size_t bytes = size_mb * 1024 * 1024;
        std::string payload(bytes, 'A');
        // make beginning and end distinct
        payload[0] = 'S'; payload[1] = 'T'; payload[2] = 'A'; payload[3] = 'R'; payload[4] = 'T';
        payload[bytes - 4] = '_'; payload[bytes - 3] = 'E'; payload[bytes - 2] = 'N'; payload[bytes - 1] = 'D';

        QString qPayload = QString::fromStdString(payload);
        auto mime = new QMimeData();
        mime->setText(qPayload);

        auto t0 = std::chrono::high_resolution_clock::now();
        cb->setMimeData(mime, QClipboard::Clipboard);
        app.processEvents();

        // Read using external wl-paste
        QProcess proc;
        proc.start("wl-paste", {"--no-newline"});
        bool finished = proc.waitForFinished(10000); // 10s timeout
        auto t1 = std::chrono::high_resolution_clock::now();
        double elapsed_ms = std::chrono::duration<double, std::milli>(t1 - t0).count();

        if (!finished) {
            std::cerr << "FAIL: Timeout reading " << size_mb << " MB payload! (Deadlock on pipe?)" << std::endl;
            proc.kill();
            return 2;
        }

        QByteArray received = proc.readAllStandardOutput();
        if (received.size() != (qsizetype)bytes) {
            std::cerr << "FAIL: Size mismatch for " << size_mb << " MB! Expected " 
                      << bytes << " bytes, got " << received.size() << std::endl;
            return 3;
        }

        if (received.startsWith("START") && received.endsWith("_END")) {
            std::cout << "PASS: " << size_mb << " MB (" << bytes << " bytes) verified in " 
                      << elapsed_ms << " ms (" << (bytes / 1024.0 / 1024.0) / (elapsed_ms / 1000.0) << " MB/s)" << std::endl;
        } else {
            std::cerr << "FAIL: Payload corruption detected in " << size_mb << " MB!" << std::endl;
            return 4;
        }
    }

    // STRESS TEST 2: Broken Pipe (Reader closes pipe prematurely)
    std::cout << "\n[TEST 2] Testing Broken Pipe / EPIPE Handling (Reader terminates after 16 bytes)..." << std::endl;
    {
        size_t bytes = 5 * 1024 * 1024; // 5 MB payload
        std::string payload(bytes, 'B');
        auto mime = new QMimeData();
        mime->setText(QString::fromStdString(payload));
        cb->setMimeData(mime, QClipboard::Clipboard);
        app.processEvents();

        // Launch reader that only reads 16 bytes and immediately terminates (causes SIGPIPE to writer)
        std::cout << "Spawning shell: wl-paste | head -c 16" << std::endl;
        int ret = system("wl-paste | head -c 16 > /dev/null");
        std::cout << "Reader exited with return code: " << ret << std::endl;

        // Process events to see if background thread survives
        app.processEvents();
        usleep(100000); // 100ms
        app.processEvents();

        // Now verify clipboard is still functional after the broken pipe
        std::cout << "Verifying KSystemClipboard is still functional after broken pipe..." << std::endl;
        auto mime2 = new QMimeData();
        mime2->setText("RECOVERY_CHECK_OK");
        cb->setMimeData(mime2, QClipboard::Clipboard);
        app.processEvents();

        QProcess checkProc;
        checkProc.start("wl-paste", {"--no-newline"});
        checkProc.waitForFinished(2000);
        QString res = QString::fromUtf8(checkProc.readAllStandardOutput());
        if (res == "RECOVERY_CHECK_OK") {
            std::cout << "PASS: Daemon survived broken pipe and recovered successfully!" << std::endl;
        } else {
            std::cerr << "FAIL: Daemon failed to recover after broken pipe! Got: " << res.toStdString() << std::endl;
            return 5;
        }
    }

    // STRESS TEST 3: High-Frequency Churn & FD Leak Check (100 rapid changes)
    std::cout << "\n[TEST 3] Testing 100 Rapid Sequential Clipboard Updates & FD Leaks..." << std::endl;
    int initial_fds = count_open_fds();
    std::cout << "FD count before churn: " << initial_fds << std::endl;

    for (int i = 0; i < 100; ++i) {
        QString item = QString("RAPID_BURST_%1_%2").arg(i).arg(rand());
        auto m = new QMimeData();
        m->setText(item);
        cb->setMimeData(m, QClipboard::Clipboard);
        app.processEvents();

        // Periodic spot-check every 20 iterations
        if (i % 20 == 19) {
            QProcess p;
            p.start("wl-paste", {"--no-newline"});
            p.waitForFinished(1000);
            QString r = QString::fromUtf8(p.readAllStandardOutput());
            if (r != item) {
                std::cerr << "FAIL: Burst item " << i << " dropped or corrupted! Expected "
                          << item.toStdString() << " got " << r.toStdString() << std::endl;
                return 6;
            }
        }
    }

    // Allow background threads to drain
    usleep(200000);
    app.processEvents();

    int final_fds = count_open_fds();
    std::cout << "FD count after 100 updates: " << final_fds << std::endl;
    std::cout << "FD delta: " << (final_fds - initial_fds) << std::endl;

    if (final_fds - initial_fds > 5) {
        std::cerr << "WARNING: File descriptor leakage detected! Delta = " << (final_fds - initial_fds) << std::endl;
    } else {
        std::cout << "PASS: File descriptor count is stable (no leak)." << std::endl;
    }

    std::cout << "\n==========================================================" << std::endl;
    std::cout << "ALL KSYSTEMCLIPBOARD EMPIRICAL TESTS PASSED!" << std::endl;
    std::cout << "==========================================================" << std::endl;
    return 0;
}
