90: //!         }
91: //!         ClipboardEvent::Changed { .. } => {}
92: //!         ClipboardEvent::Cleared { .. } => println!("Clipboard cleared"),
93: //!     }
94: //! }
95: //! # Ok(())
96: //! # }
97: //! ```
98: //!
99: //! Obtain a [`watch::CancelHandle`] from [`watch::Watcher::cancel_handle`] to stop a watcher
100: //! blocked in [`watch::Watcher::next_event`] from another thread.
101: //!
102: //! Checking if the "primary" clipboard is supported (note that this might be unnecessary depending
103: //! on your crate usage, the regular copying and pasting functions do report if the primary
