use std::io::Read;
use std::time::Duration;
use wl_clipboard_rs::paste::Seat;
use wl_clipboard_rs::watch::{ClipboardEvent, ClipboardType, Watcher};
use wl_clipboard_rs::copy::{MimeType, Options, Source};

fn get_rss_kb() -> usize {
    if let Ok(status) = std::fs::read_to_string("/proc/self/status") {
        for line in status.lines() {
            if line.starts_with("VmRSS:") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    if let Ok(val) = parts[1].parse::<usize>() {
                        return val;
                    }
                }
            }
        }
    }
    0
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== CHALLENGER 1: WL-CLIPBOARD-RS EMPIRICAL HARNESS ===");
    println!("Initial RSS: {} KB", get_rss_kb());

    // Test 1: Copy via wl-clipboard-rs
    println!("\n[TEST 1] Setting clipboard via wl-clipboard-rs copy::Options...");
    let mut opts = Options::new();
    opts.foreground(false); // fork or background

    let test_token = "RUST_WL_CLIPBOARD_RS_TOKEN_42";
    opts.copy(
        Source::Bytes(test_token.as_bytes().to_vec().into()),
        MimeType::Autodetect,
    )?;
    println!("Copy completed. Checking RSS: {} KB", get_rss_kb());

    // Test 2: Watcher verification
    println!("\n[TEST 2] Initializing Watcher...");
    let mut watcher = Watcher::new(ClipboardType::Regular, Seat::Unspecified)?;
    println!("Watcher initialized. RSS: {} KB", get_rss_kb());

    // Spawn a thread to set clipboard after 200ms
    std::thread::spawn(|| {
        std::thread::sleep(Duration::from_millis(200));
        let _ = std::process::Command::new("wl-copy")
            .arg("BURST_WATCHER_TOKEN_999")
            .output();
    });

    println!("Waiting for next event from Watcher (timeout 2s)...");
    let mut detected = false;
    // Watcher::next_event blocks, so let's observe
    if let Some(event) = watcher.next_event()? {
        match event {
            ClipboardEvent::Changed { mime_types, mut offer, .. } => {
                println!("Watcher detected ClipboardEvent::Changed!");
                println!("Offered MIME types: {:?}", mime_types);
                if mime_types.iter().any(|m| m == "text/plain") {
                    let mut s = String::new();
                    offer.receive("text/plain")?.read_to_string(&mut s)?;
                    println!("Received content: '{}'", s);
                    if s == "BURST_WATCHER_TOKEN_999" {
                        detected = true;
                    }
                }
            }
            ClipboardEvent::Cleared { .. } => {
                println!("Clipboard cleared");
            }
        }
    }

    println!("Final RSS: {} KB", get_rss_kb());
    if detected {
        println!("\nSUCCESS: wl-clipboard-rs verified functional! RSS is < 5 MB ({} KB).", get_rss_kb());
    } else {
        println!("\nFAILURE: Did not detect expected payload!");
        std::process::exit(1);
    }
    Ok(())
}
