use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;
use wl_clipboard_rs::paste::Seat;
use wl_clipboard_rs::watch::{ClipboardEvent, ClipboardType, Watcher};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== TESTING CONCURRENT EXT_DATA_CONTROL WATCHERS ON HYPRLAND ===");
    let count1 = Arc::new(AtomicUsize::new(0));
    let count2 = Arc::new(AtomicUsize::new(0));

    let c1 = count1.clone();
    let h1 = std::thread::spawn(move || {
        let mut w = Watcher::new(ClipboardType::Regular, Seat::Unspecified).unwrap();
        for _ in 0..3 {
            if let Ok(Some(ClipboardEvent::Changed { .. })) = w.next_event() {
                c1.fetch_add(1, Ordering::SeqCst);
            }
        }
    });

    let c2 = count2.clone();
    let h2 = std::thread::spawn(move || {
        let mut w = Watcher::new(ClipboardType::Regular, Seat::Unspecified).unwrap();
        for _ in 0..3 {
            if let Ok(Some(ClipboardEvent::Changed { .. })) = w.next_event() {
                c2.fetch_add(1, Ordering::SeqCst);
            }
        }
    });

    // Wait 200ms then perform 3 copies
    std::thread::sleep(Duration::from_millis(200));
    for i in 1..=3 {
        let _ = std::process::Command::new("wl-copy")
            .arg(format!("CONCURRENT_TOKEN_{}", i))
            .output();
        std::thread::sleep(Duration::from_millis(100));
    }

    h1.join().unwrap();
    h2.join().unwrap();

    let r1 = count1.load(Ordering::SeqCst);
    let r2 = count2.load(Ordering::SeqCst);
    println!("Watcher 1 received events: {}", r1);
    println!("Watcher 2 received events: {}", r2);

    if r1 >= 3 && r2 >= 3 {
        println!("PASS: Compositor cleanly multiplexes concurrent data control clients!");
    } else {
        println!("FAIL: One or more watchers dropped events! ({}, {})", r1, r2);
        std::process::exit(1);
    }
    Ok(())
}
