306:     /// Returns `Ok(None)` if cancelled via [`CancelHandle::cancel`], or `Err` on a Wayland
307:     /// communication failure.
308:     pub fn next_event<'a>(&'a mut self) -> Result<Option<ClipboardEvent<'a>>, Error> {
309:         while !self.front_matches() {
310:             if self.wait()? {
311:                 return Ok(None);
312:             }
313:         }
314:         Ok(Some(self.take_front_event()))
315:     }
316: 
317:     // Discards leading events for other clipboards/seats, returning whether a matching event is now
318:     // at the front of the queue.
319:     fn front_matches(&mut self) -> bool {
320:         while let Some(event) = self.state.selection_events.front() {
321:             if self.clipboard.includes(event.clipboard) && event.seat == self.watched {
322:                 return true;
323:             }
324:             self.state.selection_events.pop_front();
325:         }
326:         false
327:     }
328: 
329:     // Removes the front event, returning its kind and an [`Offer`] to receive from. Only call when
330:     // `front_matches` returned `true`.
331:     fn take_front_event<'a>(&'a mut self) -> ClipboardEvent<'a> {
332:         let SelectionEvent {
333:             clipboard, offer, ..
334:         } = self.state.selection_events.pop_front().unwrap();
335:         match offer {
336:             Some(SelectionOffer { offer, mime_types }) => ClipboardEvent::Changed {
337:                 clipboard,
338:                 mime_types,
339:                 offer: Offer {
340:                     watcher: self,
341:                     offer,
342:                 },
343:             },
344:             None => ClipboardEvent::Cleared { clipboard },
345:         }
346:     }
347: 
348:     // Blocks until more Wayland events arrive (or cancellation). Returns `Ok(true)` if cancelled.
349:     fn wait(&mut self) -> Result<bool, Error> {
350:         self.queue
351:             .flush()
352:             .map_err(|e| Error::WaylandCommunication(e.into()))?;
353: 
354:         if let Some(guard) = self.queue.prepare_read() {
355:             let wayland_fd = guard.connection_fd();
356:             let mut poll_fds = [
357:                 PollFd::new(&wayland_fd, PollFlags::IN | PollFlags::ERR),
358:                 PollFd::new(&self.cancel_read, PollFlags::IN),
359:             ];
360:             loop {
361:                 match rustix::event::poll(&mut poll_fds, None) {
362:                     Ok(_) => break,
363:                     Err(rustix::io::Errno::INTR) => continue,
364:                     Err(e) => {
365:                         return Err(Error::WaylandCommunication(
366:                             WaylandError::Io(e.into()).into(),
367:                         ))
368:                     }
369:                 }
370:             }
371:             // Got data on the cancel pipe, bail with `true`.
372:             if poll_fds[1].revents().contains(PollFlags::IN) {
373:                 return Ok(true);
374:             }
375:             match guard.read() {
376:                 Ok(_) => {}
377:                 Err(WaylandError::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {}
378:                 Err(e) => return Err(Error::WaylandCommunication(e.into())),
379:             }
380:         }
381: 
382:         self.queue
383:             .dispatch_pending(&mut self.state)
384:             .map_err(Error::WaylandCommunication)?;
385:         Ok(false)
386:     }
387: }
