389: /// The data offer accompanying a [`ClipboardEvent`], borrowed from its [`Watcher`].
390: pub struct Offer<'a> {
391:     watcher: &'a mut Watcher,
392:     offer: OwnedOffer,
393: }
394: 
395: impl Offer<'_> {
396:     /// Reads the clipboard content of the given MIME type into a pipe.
397:     ///
398:     /// Returns `Err(Error::ClipboardEmpty)` on a [`ClipboardEvent::Cleared`] event.
399:     pub fn receive(&mut self, mime_type: &str) -> Result<PipeReader, Error> {
400:         let (read, write) = pipe().map_err(Error::PipeCreation)?;
401:         self.offer.0.receive(mime_type.to_string(), write.as_fd());
402:         drop(write);
403:         self.watcher
404:             .queue
405:             .flush()
406:             .map_err(|e| Error::WaylandCommunication(e.into()))?;
407:         Ok(read)
408:     }
409: }
